// ---------------------------------------------------------------- number formatting (Java style)
void fmt_double(double v, bool is_float, char* out) {
  if (v != v) { strcpy(out, "NaN"); return; }
  if (isinf(v)) { strcpy(out, v > 0 ? "Infinity" : "-Infinity"); return; }
  if (v == 0) { strcpy(out, signbit(v) ? "-0.0" : "0.0"); return; }
  char buf[40];
  int maxp = is_float ? 9 : 17;
  for (int p = 1; p <= maxp; p++) {
    snprintf(buf, sizeof buf, "%.*e", p - 1, v);
    if (is_float ? (strtof(buf, nullptr) == (float)v) : (strtod(buf, nullptr) == v)) break;
  }
  // buf = [-]d.ddde[+-]XX
  bool neg = buf[0] == '-';
  const char* q = buf + (neg ? 1 : 0);
  char digits[24];
  int nd = 0;
  for (; *q && *q != 'e'; q++) if (*q != '.') digits[nd++] = *q;
  int exp = atoi(q + 1);
  while (nd > 1 && digits[nd - 1] == '0') nd--;
  digits[nd] = 0;
  char* o = out;
  if (neg) *o++ = '-';
  double a = fabs(v);
  if (a >= 1e-3 && a < 1e7) {
    if (exp >= 0) {
      for (int i = 0; i <= exp; i++) *o++ = i < nd ? digits[i] : '0';
      *o++ = '.';
      if (nd > exp + 1) for (int i = exp + 1; i < nd; i++) *o++ = digits[i];
      else *o++ = '0';
    } else {
      *o++ = '0'; *o++ = '.';
      for (int i = 0; i < -exp - 1; i++) *o++ = '0';
      for (int i = 0; i < nd; i++) *o++ = digits[i];
    }
    *o = 0;
  } else {
    *o++ = digits[0]; *o++ = '.';
    if (nd > 1) for (int i = 1; i < nd; i++) *o++ = digits[i];
    else *o++ = '0';
    snprintf(o, 8, "E%d", exp);
  }
}

static int g_http_status = -1;

// ---------------------------------------------------------------- helpers
static int ret_str(uint32_t* a, const char* s, size_t n) {
  Ref r = new_string(s, (uint32_t)n);
  if (!r) return throw_wk(WK_OOM, "out of memory");
  a[0] = r;
  return ST_OK;
}
static int ret_cstr(uint32_t* a, const char* s) { return ret_str(a, s, strlen(s)); }

static bool is_str(Ref r) { return r && H(r)->kind == K_STR; }

static int need_str(Ref r, const char* what) {
  if (!r) return throw_wk(WK_NPE, what);
  if (!is_str(r)) return vm_fatal("%s: expected a String", what);
  return ST_OK;
}
#define NEED_STR(r, what) do { int _s = need_str((r), (what)); if (_s) return _s; } while (0)

static int find(const char* h, int hl, const char* n, int nl, int from) {
  if (from < 0) from = 0;
  for (int i = from; i + nl <= hl; i++)
    if (!memcmp(h + i, n, nl)) return i;
  return -1;
}
static int rfind(const char* h, int hl, const char* n, int nl) {
  for (int i = hl - nl; i >= 0; i--)
    if (!memcmp(h + i, n, nl)) return i;
  return -1;
}
static int utf8_enc(uint32_t c, char* o) {
  if (c < 0x80) { o[0] = (char)c; return 1; }
  if (c < 0x800) { o[0] = (char)(0xC0 | (c >> 6)); o[1] = (char)(0x80 | (c & 0x3F)); return 2; }
  o[0] = (char)(0xE0 | (c >> 12)); o[1] = (char)(0x80 | ((c >> 6) & 0x3F)); o[2] = (char)(0x80 | (c & 0x3F));
  return 3;
}

// Java-compatible String.hashCode over the UTF-16 code units of a UTF-8 string
static int32_t str_hash(const uint8_t* s, uint32_t n) {
  uint32_t h = 0;
  for (uint32_t i = 0; i < n;) {
    uint32_t c = s[i];
    if (c < 0x80) i += 1;
    else if ((c & 0xE0) == 0xC0 && i + 1 < n) { c = ((c & 0x1F) << 6) | (s[i + 1] & 0x3F); i += 2; }
    else if ((c & 0xF0) == 0xE0 && i + 2 < n) { c = ((c & 0x0F) << 12) | ((s[i + 1] & 0x3F) << 6) | (s[i + 2] & 0x3F); i += 3; }
    else if ((c & 0xF8) == 0xF0 && i + 3 < n) {
      c = ((c & 0x07) << 18) | ((s[i + 1] & 0x3F) << 12) | ((s[i + 2] & 0x3F) << 6) | (s[i + 3] & 0x3F);
      i += 4;
      c -= 0x10000;
      h = 31 * h + (0xD800 + (c >> 10));
      c = 0xDC00 + (c & 0x3FF);
    } else i += 1;
    h = 31 * h + c;
  }
  return (int32_t)h;
}

static int substr(uint32_t* a, Ref s, int32_t b, int32_t e) {
  int32_t n = (int32_t)str_len(s);
  if (b < 0 || e > n || b > e) {
    char m[64];
    snprintf(m, sizeof m, "begin %d, end %d, length %d", (int)b, (int)e, (int)n);
    return throw_wk(WK_SIOOBE, m);
  }
  return ret_str(a, str_chars(s) + b, e - b);
}

static int case_map(uint32_t* a, bool upper) {
  Ref s = a[0];
  uint32_t n = str_len(s);
  Ref r = new_string(str_chars(s), n);
  if (!r) return throw_wk(WK_OOM, "out of memory");
  char* d = (char*)DATA(r);
  for (uint32_t i = 0; i < n; i++) {
    char c = d[i];
    if (upper && c >= 'a' && c <= 'z') d[i] = c - 32;
    if (!upper && c >= 'A' && c <= 'Z') d[i] = c + 32;
  }
  a[0] = r;
  return ST_OK;
}

static void class_name_of(Ref r, char* out, size_t n) {
  ObjH* h = H(r);
  if (is_array_kind(h->kind)) { snprintf(out, n, "Array"); return; }
  uint16_t id = vm.classes[h->cls].name;
  snprintf(out, n, "%.*s", (int)vm.str_len[id], (const char*)vm.str_ptr[id]);
}

static uint32_t ident_hash(Ref r) {
  uint32_t x = r * 2654435761u;
  return (x ^ (x >> 15)) & 0x7fffffff;
}

static double math1(int op, double x) {
  switch (op) {
    case 0: return sqrt(x);
    case 1: return sin(x);
    case 2: return cos(x);
    case 3: return tan(x);
    case 4: return asin(x);
    case 5: return acos(x);
    case 6: return atan(x);
    case 7: return exp(x);
    case 8: return log(x);
    case 9: return log10(x);
    case 10: return floor(x);
    case 11: return ceil(x);
    case 12: return rint(x);
    case 13: return cbrt(x);
    case 14: return sinh(x);
    case 15: return cosh(x);
    case 16: return tanh(x);
    default: return NAN;
  }
}
static double math2(int op, double x, double y) {
  switch (op) {
    case 0: return pow(x, y);
    case 1: return atan2(x, y);
    case 2: return hypot(x, y);
    case 3: return remainder(x, y);
    default: return NAN;
  }
}

